test('shared library references isolate role and group choices, track edits, preserve legacy CSS and safely fall back after deletion',()=>{const {state,data,group}=created();state.groupChats=data;state.settings={beautifyCss:{online:'.bubble{color:gray}'},beautifyBackgrounds:{online:''},onlineBeautifyLibrary:{active:'default',items:[{id:'rose',name:'玫瑰',css:'.bubble{color:red}',background:''}]}};const builtins=[{id:'default',name:'默认',css:''},{id:'wechat',name:'仿微信',css:'white-controls'},{id:'imessage',name:'仿iMessage',css:'gray-controls'}];Appearance.assign(state,builtins,{roles:[0],groups:[group.id],schemeId:'rose'});Appearance.assign(state,builtins,{roles:[1],schemeId:'imessage'});assert.equal(Appearance.resolve(state,builtins,{role:state.characters[0]}).css,'.bubble{color:red}');assert.equal(Appearance.resolve(state,builtins,{role:state.characters[1]}).css,'gray-controls');assert.equal(Appearance.resolve(state,builtins,{role:state.characters[2]}).css,'.bubble{color:gray}');state.settings.onlineBeautifyLibrary.items[0].css='edited-rose';assert.match(Appearance.resolve(state,builtins,{group}).css,/edited-rose/);assert.equal(Appearance.resolve(state,builtins,{role:state.characters[0]}).css,'edited-rose');state.settings.onlineBeautifyLibrary.items=[];assert.equal(Appearance.resolve(state,builtins,{role:state.characters[0]}).id,'default');assert.equal(Appearance.resolve(state,builtins,{role:state.characters[0]}).css,'');assert.equal(Appearance.resolve(state,builtins,{role:state.characters[1]}).css,'gray-controls');const legacy={settings:{followOnline:false,theme:'wechat',css:'extra-css',background:'https://example.test/image.png'}};assert.equal(Appearance.resolve(state,builtins,{group:legacy}).css,'white-controls\nextra-css');assert.throws(()=>Appearance.assign(state,builtins,{roles:[0],schemeId:'missing'}),/不存在/)});
