test('group video phone call control is separate from composer send and reroll, which replaces only the latest response and restores it on failure',async()=>{const f=boot(),w=f.w;try{createClicks(w);await flush();w.eval(`window.videoVersion=0;requestConfiguredChatCompletion=async(api,model,prompt)=>{window.videoVersion++;window.latestVideoPrompt=prompt;const roles=state.groupChats.items[0].members.filter(m=>m.type==='role');return {choices:[{message:{content:JSON.stringify({attendance:roles.map(m=>({speakerId:m.id,join:true,reason:'有空'})),messages:[{speakerId:roles[0].id,text:'版本'+window.videoVersion}]})}}]}}`);w.document.querySelector('[data-group-functions]').click();w.document.querySelector('[data-group-feature="video"]').click();const screen=w.document.querySelector('.group-video-screen'),controls=screen.querySelector('.video-call-controls'),form=screen.querySelector('form');assert.equal(controls.querySelectorAll(':scope>button').length,5);assert.equal(controls.firstElementChild.dataset.groupVideoCall,'');assert.ok(controls.firstElementChild.querySelector('svg path'));assert.ok(form.querySelector('[type="submit"]'));assert.ok(form.querySelector('[data-group-video-reply]'));controls.firstElementChild.click();await waitGroupVideoReply(w);assert.match(w.latestVideoPrompt,/本次是呼叫或再次邀请/);form.elements.text.value='新的问题';form.requestSubmit();form.querySelector('[data-group-video-reply]').click();await waitGroupVideoReply(w);assert.match(screen.querySelector('[role="log"]').textContent,/版本1.*新的问题.*版本2/);w.eval('window.finishVideoReroll=null;requestConfiguredChatCompletion=()=>new Promise(resolve=>window.finishVideoReroll=resolve)');form.querySelector('[data-group-video-reply]').click();assert.ok(!screen.querySelector('[role="log"]').textContent.includes('版本2'));assert.ok(screen.querySelector('[role="log"]').textContent.includes('版本1'));await flush();w.finishVideoReroll({choices:[{message:{content:JSON.stringify({attendance:w.eval('state.groupChats.items[0].members.filter(m=>m.type==="role").map(m=>({speakerId:m.id,join:true,reason:"有空"}))'),messages:[{speakerId:w.eval('state.groupChats.items[0].members[1].id'),text:'版本3'}]})}}]});await waitGroupVideoReply(w);assert.ok(screen.querySelector('[role="log"]').textContent.includes('版本3'));w.eval('requestConfiguredChatCompletion=async()=>{throw Error("本轮失败")}');form.querySelector('[data-group-video-reply]').click();await waitGroupVideoReply(w);assert.ok(screen.querySelector('[role="log"]').textContent.includes('版本3'));assert.match(screen.querySelector('[data-group-video-status]').textContent,/本轮失败/);assert.deepEqual(f.errors,[])}finally{await w.IrisGroupVideo?.close();w.close()}});
