test('private and group camera windows drag within the call stage, reserve nearby text space and release their handlers on close',async()=>{for(const groupCall of [false,true]){const f=boot(),w=f.w;try{if(groupCall){createClicks(w);await flush();w.document.querySelector('[data-group-functions]').click();w.document.querySelector('[data-group-feature="video"]').click()}else w.openVideoComposer();const screen=w.document.querySelector(groupCall?'.group-video-screen':'#videoCallScreen'),stage=screen.querySelector('.video-call-stage'),pip=screen.querySelector('.video-call-pip'),log=screen.querySelector('.video-call-messages'),rect=(left,top,width,height)=>({left,top,right:left+width,bottom:top+height,width,height});stage.getBoundingClientRect=()=>rect(10,60,400,500);pip.getBoundingClientRect=()=>rect(10+(pip.style.left?parseFloat(pip.style.left):280),60+(pip.style.left?parseFloat(pip.style.top):20),106,141);log.getBoundingClientRect=()=>rect(27,100,366,450);const row=w.document.createElement('article');row.className=groupCall?'group-video-line':'video-call-message';row.getBoundingClientRect=()=>rect(27,120,180,40);log.append(row);w.bindVideoPipDrag(screen);await new Promise(resolve=>setTimeout(resolve,45));assert.equal(row.style.getPropertyValue('--call-pip-right-gap'),'115px');const pointer=(type,x,y)=>{const event=new w.MouseEvent(type,{bubbles:true,cancelable:true,button:0,clientX:x,clientY:y});Object.defineProperty(event,'pointerId',{value:1});pip.dispatchEvent(event)};pointer('pointerdown',300,100);pointer('pointermove',9999,9999);assert.equal(pip.style.left,'286px');assert.equal(pip.style.top,'351px');pointer('pointermove',-9999,-9999);assert.equal(pip.style.left,'8px');assert.equal(pip.style.top,'8px');pointer('pointerup',0,0);await new Promise(resolve=>setTimeout(resolve,45));assert.equal(row.style.getPropertyValue('--call-pip-left-gap'),'109px');assert.equal(pip.classList.contains('is-dragging'),false);if(groupCall)await w.IrisGroupVideo.close();else w.closeVideoCall();assert.equal(screen.videoPipCleanup,undefined);assert.equal(screen.isConnected,false);assert.deepEqual(f.errors,[])}finally{await w.IrisGroupVideo?.close();w.closeVideoCall();w.close()}}});
